    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Sprite2D.region_rect setter: wrong type");
    }

    double tmp_x_value, tmp_y_value, tmp_w_value, tmp_h_value;
    JSValue jpos_value = JS_GetPropertyStr(ctx, argv[1], "position");
    JSValue jsize_value = JS_GetPropertyStr(ctx, argv[1], "size");
    JSValue jpx_value = JS_GetPropertyStr(ctx, jpos_value, "x");
