    JS_ToFloat64(ctx, &tmp_h_value, jsy_value);
    JS_FreeValue(ctx, jpx_value); JS_FreeValue(ctx, jpy_value);
    JS_FreeValue(ctx, jsx_value); JS_FreeValue(ctx, jsy_value);
    JS_FreeValue(ctx, jpos_value); JS_FreeValue(ctx, jsize_value);
    Rect2 value(tmp_x_value, tmp_y_value, tmp_w_value, tmp_h_value);
    typed_obj->set_region_rect(value);
    return JS_UNDEFINED;
